t.script:
var _instScript = document.currentScript;
var _installationBookingInitialized = false;
function initInstallationBooking() {
    if (_installationBookingInitialized) return;
    if (!document.getElementById('instSubmitError')) {
        setTimeout(initInstallationBooking, 10);
        return;
    }
    _installationBookingInitialized = true;
    try {
    var soId = parseInt(_instScript.getAttribute('data-so-id'));
    var selectedRouteId = null;
    var rpc = odoo.loader.modules.get("@web/core/network/rpc").rpc;
    function translatedText(id) {
        return document.getElementById(id).textContent.trim();
    }
    var dayNames = ['instSunday','instMonday','instTuesday','instWednesday','instThursday','instFriday','instSaturday'].map(translatedText);
    var monthNames = ['instJanuary','instFebruary','instMarch','instApril','instMay','instJune','instJuly','instAugust','instSeptember','instOctober','instNovember','instDecember'].map(translatedText);

    function dateStr(d) {
        return d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0');
    }

    function showRouteError() {
        var empty = document.getElementById('routeEmpty');
        empty.querySelector('p').textContent = translatedText('instLoadError');
        empty.classList.remove('d-none');
    }

    async function loadRoutes() {
        try {
            var data = await rpc('/my/installation/routes', {});
            document.getElementById('routeLoading').classList.add('d-none');
            if (data.success && data.routes && data.routes.length) {
                renderWeek(data.routes);
                document.getElementById('routesContainer').classList.remove('d-none');
            } else {
                document.getElementById('routeEmpty').classList.remove('d-none');
            }
        } catch {
            document.getElementById('routeLoading').classList.add('d-none');
            showRouteError();
        }
    }

    function renderWeek(routes) {
        var today = new Date(); today.setHours(0,0,0,0);
        var byDate = {};
        routes.forEach(function(r){ if (!byDate[r.date]) byDate[r.date] = []; byDate[r.date].push(r); });
        var lastSlotDate = null;
        routes.forEach(function(r){ if (!lastSlotDate || r.date > lastSlotDate) lastSlotDate = r.date; });
        var maxDays = 28;
        var days = [];
        for (var i = 0; i <= maxDays; i++) {
            var d = new Date(today); d.setDate(today.getDate() + i);
            var ds = dateStr(d);
            if (lastSlotDate && ds > lastSlotDate) break;
            days.push(d);
        }

        var wrapper = document.getElementById('installationBookingDays');
        wrapper.replaceChildren();
        days.forEach(function(d) {
            var ds = dateStr(d);
            var slots = byDate[ds] || [];
            var slide = document.createElement('div');
            slide.className = 'booking-day';
            var card = document.createElement('div');
            card.className = 'day-card' + (slots.length ? ' has-routes' : '');
            var dayName = document.createElement('div');
            dayName.className = 'day-name';
            dayName.textContent = dayNames[d.getDay()];
            var dayNumber = document.createElement('div');
            dayNumber.className = 'day-num';
            dayNumber.textContent = String(d.getDate());
            card.append(dayName, dayNumber);
            if (slots.length) {
                slots.forEach(function(slot){
                    var tag = document.createElement('button');
                    var routeName = slot.route_name || translatedText('instAppointment');
                    tag.type = 'button';
                    tag.className = 'route-tag';
                    tag.dataset.routeId = String(slot.id);
                    tag.dataset.routeName = dayNames[d.getDay()] + ' ' + d.getDate() + ' ' + monthNames[d.getMonth()] + ' - ' + routeName;
                    var label = document.createElement('small');
                    label.textContent = routeName;
                    tag.appendChild(label);
                    tag.addEventListener('click', function(){
                        document.querySelectorAll('#inst-form .route-tag').forEach(function(item){ item.classList.remove('selected'); });
                        tag.classList.add('selected');
                        selectedRouteId = tag.dataset.routeId;
                        document.getElementById('selectedSlotInfo').textContent = tag.dataset.routeName;
                        document.getElementById('selectedSlotDisplay').classList.remove('d-none');
                        document.getElementById('submitInstBtn').removeAttribute('disabled');
                    });
                    card.appendChild(tag);
                });
            } else {
                var noRoutes = document.createElement('div');
                noRoutes.className = 'day-no-routes mt-2';
                noRoutes.textContent = translatedText('instNone');
                card.appendChild(noRoutes);
            }
            slide.appendChild(card);
            wrapper.appendChild(slide);
        });
    }

    function setSubmitButton(button, loading) {
        var icon = document.createElement('i');
        icon.className = loading ? 'fa fa-spinner fa-spin me-2' : 'fa fa-check me-2';
        button.replaceChildren(icon, document.createTextNode(loading ? translatedText('instBooking') : translatedText('instConfirm')));
    }

    function showSubmitError(message) {
        var errorPanel = document.getElementById('instInlineError');
        document.getElementById('instInlineErrorMessage').textContent = message;
        errorPanel.classList.remove('d-none');
        errorPanel.focus();
    }

    function clearSubmitError() {
        document.getElementById('instInlineError').classList.add('d-none');
    }

    document.getElementById('submitInstBtn').addEventListener('click', async function(){
        var btn = this;
        clearSubmitError();
        btn.setAttribute('disabled','disabled');
        setSubmitButton(btn, true);
        try {
            var data = await rpc('/my/installation/submit', {
                sale_order_id: soId,
                route_id: selectedRouteId,
            });
            if (data.success) {
                window.location.href = data.redirect;
            } else {
                showSubmitError(data.error || translatedText('instSubmitError'));
                btn.removeAttribute('disabled');
                setSubmitButton(btn, false);
            }
        } catch {
            showSubmitError(translatedText('instSubmitError'));
            btn.removeAttribute('disabled');
            setSubmitButton(btn, false);
        }
    });

    loadRoutes();
    } catch (error) {
        _installationBookingInitialized = false;
        setTimeout(initInstallationBooking, 50);
    }
}
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initInstallationBooking);
} else {
    initInstallationBooking();
}
setTimeout(initInstallationBooking, 0);
